-- DoujinHentai.net plugin for Dreamora
-- Spanish manga/doujinshi source

id = "doujinhentai"
name = "DoujinHentai"
version = "1.0.2"
baseUrl = "https://doujinhentai.net/"
icon = "https://raw.githubusercontent.com/Stlucifer15t/external-sources/refs/heads/main/icons/doujinhentai.png"
language = {"es", "en"}
content_type = "manga"

-- ── Хелперы ──

-- Old builds ship no require_lib: keep the plugin loadable (a top-level
-- error would drop it from the source list) and fail with a visible
-- message on the first call instead. require_lib caches loaded libs.
local function lib(id)
    if type(require_lib) ~= "function" then
        show_error("Se requiere actualizar Dreamora",
            "Este plugin necesita las bibliotecas compartidas")
        error("Se requiere actualizar Dreamora (require_lib)", 0)
    end
    return require_lib(id)
end

local function absUrl(href) return lib("urls").absUrl(baseUrl, href) end

-- Кэш ответа ведёт общий fetch lib; ретрай с паузой — специфика сайта.
local function fetchPage(url)
    local body = lib("fetch").page(url)
    if not body then
        sleep(500)
        body = lib("fetch").page(url)
    end
    return body
end

local function getSlug(bookUrl)
    return string.match(bookUrl, "/manga%-hentai/([^/]+)")
end

local function extractJsonFromScript(html, typeAttr)
    local selector = "script[type='" .. typeAttr .. "']"
    local el = html_select_first(html, selector)
    if el then
        return el.html
    end
    return nil
end

-- ── Каталог ──

function getCatalogList(index)
    local page = lib("catalog").nextIndex(index)
    local url = baseUrl .. "lista-manga-hentai/?orderby=last&page=" .. page
    local html = fetchPage(url)
    if not html then return { items = {}, hasNext = false } end

    local items = {}
    local cards = html_select(html, "div.group.bg-white.rounded-2xl")
    for _, card in ipairs(cards) do
        local href = html_attr(card.html, "a.block[href]", "href") or ""
        local titleEl = html_select_first(card.html, "h3.font-bold")
        local cover = html_attr(card.html, "img", "src") or ""
        local title = titleEl and string_clean(html_text(titleEl)) or ""
        if href ~= "" and title ~= "" then
            table.insert(items, {
                title = title,
                url = absUrl(href),
                cover = absUrl(cover)
            })
        end
    end

    return {
        items = items,
        hasNext = #items >= 18
    }
end

function getCatalogSearch(index, query)
    local url = baseUrl .. "search-live?query=" .. lib("catalog").urlEncode(query or "")
    local r = http_get(url)
    if not r.success then
        sleep(500)
        r = http_get(url)
    end
    if not r.success then return { items = {}, hasNext = false } end

    local ok, data = pcall(json_parse, r.body)
    if not ok or not data or not data.results then
        return { items = {}, hasNext = false }
    end

    local items = {}
    for _, result in ipairs(data.results) do
        if result.url and result.name then
            table.insert(items, {
                title = string_clean(result.name),
                url = absUrl(result.url),
                cover = absUrl(result.cover or "")
            })
        end
    end

    return {
        items = items,
        hasNext = false
    }
end

